import os

log_path = "logs/app-2026-09-17.log"
if os.path.exists(log_path):
    print(f"File exists: {log_path}, size: {os.path.getsize(log_path)} bytes")
    with open(log_path, "r") as f:
        lines = [f.readline() for _ in range(20)]
    print("Sample lines:")
    for l in lines:
        print(l.strip())
else:
    print(f"File not found: {log_path}")
    print("Available logs:")
    for root, dirs, files in os.walk("."):
        for f in files:
            if "log" in f or "2026" in f:
                print(os.path.join(root, f))
